import React, { useState } from 'react';
import chatBgImg from '../assets/nen_ten_web.jpg'; // Dùng ảnh bạn gửi làm nền khung chat

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('all');

    return (
        <div style={{...styles.mainWrapper, backgroundImage: `url(${chatBgImg})` }} className="glass-card fade-in">
            {/* Header Tabs */}
            <div style={styles.headerTabs}>
                <button 
                    onClick={() => setTabActive('all')}
                    style={{...styles.tabBtn, backgroundColor: tabActive === 'all' ? '#333' : 'rgba(255,255,255,0.5)', color: tabActive === 'all' ? '#fff' : '#333'}}
                >
                    Mọi người
                </button>
                <button 
                    onClick={() => setTabActive('private')}
                    style={{...styles.tabBtn, backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.5)', color: tabActive === 'private' ? '#fff' : '#333'}}
                >
                    Gửi riêng
                </button>
            </div>

            <div style={styles.contentBody}>
                {tabActive === 'all' ? (
                    <div style={styles.fullChat} className="fade-in">
                        <div style={styles.history}>
                            <div style={styles.msg}>
                                <div style={styles.avatar}>105</div>
                                <div style={styles.bubble}>Thông báo: Họp cư dân vào tối chủ nhật!</div>
                            </div>
                        </div>
                        <div style={styles.inputRow}>
                            <input style={styles.input} placeholder="Nhập thông báo chung..." />
                            <button style={styles.sendBtn}>Gửi</button>
                        </div>
                    </div>
                ) : (
                    <div style={styles.privateView} className="fade-in">
                        <div style={styles.roomSidebar}>
                            <div style={styles.roomGrid}>
                                {[101, 102, 103, 104, 201, 202, 203, 204].map(id => (
                                    <div key={id} className="room-item">{id}</div>
                                ))}
                            </div>
                        </div>
                        <div style={styles.privateChatArea}>
                            <div style={styles.history}>Chọn cư dân để gửi tin nhắn riêng</div>
                            <div style={styles.inputRow}>
                                <input style={styles.input} placeholder="Nhập tin nhắn riêng..." />
                                <button style={{...styles.sendBtn, backgroundColor: '#8b5e5e'}}>Gửi</button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    mainWrapper: { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundSize: 'cover', backgroundPosition: 'center', overflow: 'hidden' },
    headerTabs: { padding: '20px', display: 'flex', gap: '15px' },
    tabBtn: { padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', cursor: 'pointer' },
    contentBody: { flex: 1, display: 'flex', padding: '20px', overflow: 'hidden' },
    fullChat: { flex: 1, display: 'flex', flexDirection: 'column' },
    privateView: { flex: 1, display: 'flex', gap: '20px' },
    roomSidebar: { width: '150px', backgroundColor: 'rgba(255,255,255,0.3)', borderRadius: '20px', padding: '15px' },
    roomGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' },
    privateChatArea: { flex: 1, display: 'flex', flexDirection: 'column' },
    history: { flex: 1, padding: '10px', color: '#fff' },
    msg: { display: 'flex', gap: '10px', alignItems: 'center' },
    avatar: { width: '35px', height: '35px', borderRadius: '50%', backgroundColor: '#333', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' },
    bubble: { backgroundColor: 'rgba(255,255,255,0.9)', padding: '12px 18px', borderRadius: '18px 18px 18px 0', fontSize: '13px' },
    inputRow: { display: 'flex', gap: '10px' },
    input: { flex: 1, padding: '15px', borderRadius: '15px', border: 'none', backgroundColor: '#fff', outline: 'none' },
    sendBtn: { padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold' }
};

export default QuanLyThongBao;
